/* Audit Console tokens — generated from the design system's tokens.json. Dark is the primary theme. */
:root {
  color-scheme: dark;
  --bg-app: #131517;
  --bg-card: #0f1112;
@import url('https://fonts.googleapis.com/css2?family=Geist:wght@400;500;600&family=Geist+Mono:wght@400;500&display=swap

/* Hallmark · genre: modern-minimal · theme: custom (studied from the reference dashboard) · pre-emit critique: P4 H5

input.content:
/* Spend Radar site — extends the Audit Console design system (tokens.css + audit-console.css).
 * Layout concept: the console shell from the system; one orchestrated moment per screen, everything else quiet.
 * Motion: heavy ease-out ("settle"), staggered entrances, things land and stop. Nothing loops, numbers never count. */

:root {
  --ease-settle: cubic-bezier(.16, 1, .3, 1);
  --ease-press: cubic-bezier(.3, 0, .2, 1);
  --dur-enter: .72s;
  --stagger: 70ms;
}

body { background: var(--bg-app); color: var(--text); }
a { color: inherit; }
.ac-main { view-transition-name: main; width: 100%; margin: 0 auto; }
.ac-nav { position: sticky; top: 0; height: 100vh; overflow-y: auto; }
.ac-brand { cursor: default; }
.ac-brand small { display: block; font-size: 12px; font-weight: 400; color: var(--text-tertiary); letter-spacing: 0; }
.sr-nav-foot { margin-top: var(--space-8); padding: var(--space-4) var(--space-3) 0; border-top: 1px solid var(--border-row); font-size: 13px; line-height: 19px; color: var(--text-tertiary); }
.sr-nav-foot b { color: var(--text-secondary); font-weight: 500; }

/* Top bar: sticky, quiet */
.ac-topbar { position: sticky; top: env(safe-area-inset-top, 0px); z-index: 5; background: var(--bg-app); }
.sr-tabs { display: none; }
@media (max-width: 960px) {
  .sr-tabs { display: flex; gap: var(--space-1); overflow-x: auto; padding: var(--space-2) var(--space-4); border-bottom: 1px solid var(--border); position: sticky; top: calc(var(--topbar-height) + env(safe-area-inset-top, 0px)); z-index: 4; background: var(--bg-app); scrollbar-width: none; }
  .sr-tabs a { flex: none; padding: 6px var(--space-3); border-radius: var(--radius-sm); font-size: 14px; color: var(--text-secondary); text-decoration: none; white-space: nowrap; }
  .sr-tabs a[aria-current="page"] { background: var(--bg-chip); color: var(--text); }
  .ac-topbar { height: 64px; }
}

/* Page head */
.sr-badges { margin: calc(-1 * var(--space-2)) 0 var(--space-6); }
.sr-section { margin-top: var(--space-5); }
.sr-section-title { display: flex; align-items: baseline; justify-content: space-between; gap: var(--space-4); flex-wrap: wrap; margin: var(--space-10) 0 var(--space-4); }
.sr-section-title h2 { margin: 0; font-size: 22px; line-height: 28px; font-weight: 600; letter-spacing: -.02em; }
.sr-section-title p { margin: 0; font-size: 14px; color: var(--text-tertiary); max-width: 60ch; }
.sr-muted { color: var(--text-tertiary); }
.sr-secondary { color: var(--text-secondary); }
.sr-mono { font-family: var(--font-mono); font-size: 12px; }
.sr-empty { padding: var(--space-6); border: 1px dashed var(--border-row); border-radius: var(--radius-md); color: var(--text-tertiary); font-size: 14px; }

/* Hero headline: words rise out of their own line, like type set on a press */
.ac-hero-xl .w { display: inline-block; overflow: hidden; vertical-align: top; padding-bottom: .06em; margin-bottom: -.06em; }
.ac-hero-xl .w > span { display: inline-block; }
.ac-hero-xl em { background: linear-gradient(var(--up), var(--up)) no-repeat 0 92% / 100% 3px; padding-bottom: 2px; }

/* The verdict's dot grid answers the cursor: dots near it brighten. The only ornament in the system. */
.ac-verdict::before { content: ""; position: absolute; inset: 0; pointer-events: none; opacity: 0; transition: opacity .4s ease;
  background-image: radial-gradient(var(--text-tertiary) 1px, transparent 1px); background-size: 16px 16px; background-position: -8px -8px;
  -webkit-mask-image: radial-gradient(circle 220px at var(--mx, 50%) var(--my, 50%), #000 0%, transparent 100%);
  mask-image: radial-gradient(circle 220px at var(--mx, 50%) var(--my, 50%), #000 0%, transparent 100%); }
@media (hover: hover) and (pointer: fine) { .ac-verdict:hover::before { opacity: .55; } }
.ac-mrow { cursor: pointer; border-radius: var(--radius-xs); transition: background-color .15s ease; }
@media (hover: hover) { .ac-mrow:hover { background: var(--bg-field); } }
.ac-mrow:focus-visible { outline-offset: 0; }
.ac-mrow .ac-avatar { margin-left: var(--space-1); }
.ac-cells { flex-wrap: wrap; justify-content: flex-end; max-width: 120px; }
.ac-mscore.ac-up { color: var(--up); }

/* The loop: how one run works */
.sr-loop { position: relative; display: grid; grid-template-columns: repeat(7, minmax(0, 1fr)); gap: var(--space-3); }
.sr-loop::before { content: ""; position: absolute; left: 4%; right: 4%; top: 27px; height: 1px; background: var(--border-control); }
.sr-node { position: relative; display: flex; flex-direction: column; gap: var(--space-2); min-width: 0; }
.sr-node-dot { position: relative; z-index: 1; display: grid; place-items: center; width: 54px; height: 54px; border-radius: var(--radius-full); background: var(--bg-card); border: 1px solid var(--border-control); color: var(--text-secondary); }
.sr-node-dot .ac-icon { width: 20px; height: 20px; }
.sr-node--llm .sr-node-dot { color: var(--accent); border-color: var(--accent); }
.sr-node h4 { margin: var(--space-2) 0 0; font-size: 15px; line-height: 20px; font-weight: 600; }
.sr-node p { margin: 0; font-size: 13px; line-height: 19px; color: var(--text-tertiary); }
.sr-who { align-self: flex-start; }
.sr-pulse { position: absolute; z-index: 2; top: 23px; left: 4%; width: 9px; height: 9px; border-radius: var(--radius-full); background: var(--up); opacity: 0; }
.sr-loop-foot { display: flex; gap: var(--space-5); flex-wrap: wrap; margin-top: var(--space-5); padding-top: var(--space-4); border-top: 1px solid var(--border-row); font-size: 13px; color: var(--text-tertiary); }
.sr-loop-foot span { display: inline-flex; align-items: center; gap: var(--space-2); }
.sr-key { width: 10px; height: 10px; border-radius: var(--radius-full); border: 1px solid var(--border-control); }
.sr-key--llm { border-color: var(--accent); }
@media (max-width: 1100px) {
  .sr-loop { grid-template-columns: repeat(4, minmax(0, 1fr)); row-gap: var(--space-6); }
  .sr-loop::before, .sr-pulse { display: none; }
}
@media (max-width: 560px) { .sr-loop { grid-template-columns: repeat(2, minmax(0, 1fr)); } }

/* ProofChain additions: a drawn strike, a replay button */
.ac-struck { position: relative; text-decoration: none; display: inline-block; }
.ac-struck::after { content: ""; position: absolute; left: -3px; right: -3px; top: 52%; height: 3px; border-radius: 2px; background: var(--down); transform-origin: left center; }
.sr-claim-sub { font-size: 13px; line-height: 19px; color: var(--text-tertiary); }
.sr-quote { margin: 0; font-size: 14px; line-height: 21px; color: var(--text-secondary); }
.sr-quote b { color: var(--text); font-weight: 500; }
.sr-verdict-word { font-weight: 600; }
.ac-step--warn { border-color: var(--warn); background: var(--warn-soft); }
.ac-step--warn .ac-claimnum { color: var(--warn); }
.ac-step--up { border-color: var(--up); background: var(--up-soft); }
.ac-step--up .ac-claimnum { color: var(--up); }
.sr-chain-foot { display: flex; justify-content: space-between; align-items: center; gap: var(--space-3); flex-wrap: wrap; margin-top: var(--space-4); font-size: 13px; color: var(--text-tertiary); }

/* Cards that respond with weight: a short lift, a firmer border, a press */
.sr-lift { transition: transform .35s var(--ease-settle), border-color .15s ease, background-color .15s ease; }
@media (hover: hover) { .sr-lift:hover { transform: translateY(-2px); border-color: var(--border-control); } }
.sr-lift:active { transform: translateY(0) scale(.996); transition-duration: .12s; }
button.sr-lift, a.sr-lift { text-align: left; font: inherit; color: inherit; text-decoration: none; cursor: pointer; }

/* Company switcher */
.sr-switch { display: flex; gap: var(--space-2); flex-wrap: wrap; margin-bottom: var(--space-6); }
.sr-chip { display: inline-flex; align-items: center; gap: var(--space-2); height: 36px; padding: 0 var(--space-3) 0 var(--space-1); border-radius: var(--radius-full); border: 1px solid var(--border); background: var(--bg-card); color: var(--text-secondary); font: 500 14px/20px var(--font-sans); cursor: pointer; transition: border-color .15s ease, color .15s ease, background-color .15s ease; }
.sr-chip .ac-avatar { width: 28px; height: 28px; font-size: 12px; }
@media (hover: hover) { .sr-chip:hover { color: var(--text); border-color: var(--border-control); } }
.sr-chip[aria-pressed="true"] { color: var(--text); background: var(--bg-chip); border-color: var(--border-control); }
.sr-chip[aria-pressed="true"] .ac-avatar { background: var(--text); color: var(--bg-card); }
.sr-select { height: var(--control-height); padding: 0 var(--space-8) 0 var(--space-3); border-radius: var(--radius-md); border: 1px solid var(--border); background: var(--bg-field); color: var(--text); font: 400 13px/18px var(--font-mono); max-width: 100%; }
.sr-runpick { display: flex; gap: var(--space-3); align-items: center; flex-wrap: wrap; }

/* Chart columns are buttons on Run detail */
.ac-chart .col { cursor: pointer; }
.ac-chart .col:focus-visible { outline: none; }
.ac-chart .col:focus-visible .ghost { stroke: var(--focus); stroke-width: 2; }
.ac-chart .bar-accent { fill: var(--accent); }
.ac-chart .bar-neutral { fill: var(--text-secondary); }
.ac-chart .col.is-current .ghost { fill: var(--bg-chip); }
.sr-chart-note { margin-top: var(--space-2); font-size: 13px; color: var(--text-tertiary); }

/* Run replay timeline */
.sr-plan { margin: 0 0 var(--space-5); padding: var(--space-4) var(--space-5); border-radius: var(--radius-md); background: var(--bg-app); border: 1px solid var(--border); font-size: 14px; line-height: 22px; color: var(--text-secondary); max-width: 90ch; }
.sr-plan b { display: block; margin-bottom: var(--space-1); font-size: 12px; letter-spacing: .08em; text-transform: uppercase; color: var(--accent); font-weight: 500; }
.sr-tl { position: relative; display: grid; gap: 0; }
.sr-tl::before { content: ""; position: absolute; left: 11px; top: 14px; bottom: 14px; width: 1px; background: var(--border-row); }
.sr-tl-progress { position: absolute; left: 11px; top: 14px; width: 1px; height: 0; background: var(--up); transition: height .12s linear; }
.sr-tl-row { position: relative; display: grid; grid-template-columns: 24px minmax(0, 1fr); gap: var(--space-3); padding: var(--space-2) 0; transition: opacity .3s ease; }
.sr-tl-dot { position: relative; z-index: 1; width: 9px; height: 9px; margin: 7px 0 0 7px; border-radius: var(--radius-full); background: var(--up); box-shadow: 0 0 0 4px var(--bg-card); }
.sr-tl-row--failed .sr-tl-dot { background: var(--down); }
.sr-tl-row--child { padding-left: var(--space-6); }
.sr-tl-row--child .sr-tl-dot { background: var(--accent); }
.sr-tl-head { display: flex; flex-wrap: wrap; align-items: center; gap: var(--space-2); font-size: 14px; line-height: 20px; }
.sr-tl-head .ac-tag { flex: none; }
.sr-tl-target { color: var(--text); font-weight: 500; overflow-wrap: anywhere; }
.sr-tl-reason { margin-top: 2px; font-size: 13px; line-height: 19px; color: var(--text-tertiary); }
.sr-decision { margin: var(--space-3) 0 var(--space-2); padding: var(--space-4); border-radius: var(--radius-md); border: 1px solid var(--border-row); background: var(--bg-app); display: grid; gap: var(--space-3); }
.sr-decision-check { font-family: var(--font-mono); font-size: 12px; line-height: 18px; color: var(--down); overflow-wrap: anywhere; }
.sr-opts { display: flex; gap: var(--space-2); flex-wrap: wrap; }
.sr-opt { display: inline-flex; align-items: center; gap: var(--space-1); height: 26px; padding: 0 var(--space-2); border-radius: var(--radius-xs); border: 1px solid var(--border-row); font: 500 12px/16px var(--font-mono); color: var(--text-tertiary); }
.sr-opt--chosen { color: var(--accent); background: var(--accent-soft); border-color: var(--accent); }
.sr-opt--chosen.is-rule { color: var(--text); background: var(--bg-chip); border-color: var(--border-control); }
.sr-opt small { font: 400 11px/14px var(--font-sans); color: var(--text-tertiary); }
.sr-decision-why { font-size: 14px; line-height: 21px; color: var(--text-secondary); }
.sr-decision-why b { color: var(--text); font-weight: 500; }
.sr-tl-scroll { max-height: 640px; overflow-y: auto; padding-right: var(--space-2); overscroll-behavior: contain; }

/* Findings */
.sr-findings { display: grid; gap: var(--space-3); }
.sr-finding { padding: var(--space-4) var(--space-5); border-radius: var(--radius-md); border: 1px solid var(--border-row); background: var(--bg-card); }
.sr-finding summary { list-style: none; cursor: pointer; display: grid; grid-template-columns: auto minmax(0, 1fr) auto; gap: var(--space-3); align-items: start; }
.sr-finding summary::-webkit-details-marker { display: none; }
.sr-finding-text { font-size: 14px; line-height: 21px; color: var(--text); }
.sr-finding-conf { display: grid; justify-items: end; gap: 6px; font-size: 12px; color: var(--text-tertiary); font-variant-numeric: tabular-nums; white-space: nowrap; }
.sr-finding .ac-notes { margin-top: var(--space-4); }
.sr-finding[open] { border-color: var(--border-control); }

/* Stat tiles with a subtitle line */
.ac-stats .ac-card { position: relative; }

/* Before / after */
.sr-ba-list { display: grid; gap: var(--space-5); }
.sr-ba-runs { display: grid; gap: var(--space-2); margin-top: var(--space-3); }
.sr-ba-run { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: var(--space-1) var(--space-3); align-items: center; padding: var(--space-3) var(--space-4); border-radius: var(--radius-sm); background: var(--bg-app); border: 1px solid var(--border-row); }
.sr-ba-run .ac-cells { justify-content: flex-start; max-width: none; }
.sr-ba-score { font-size: 22px; line-height: 28px; font-weight: 600; letter-spacing: -.02em; font-variant-numeric: tabular-nums; }
.sr-ba-meta { grid-column: 1 / -1; font-size: 12px; color: var(--text-tertiary); }
.sr-ba-side-label { font-size: 12px; letter-spacing: .08em; text-transform: uppercase; color: var(--text-tertiary); font-weight: 500; }

/* Business */
.sr-biz { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 320px), 1fr)); gap: var(--space-5); }
.sr-dl { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: var(--space-3) var(--space-4); margin: 0; font-size: 15px; }
.sr-dl dt { color: var(--text-secondary); }
.sr-dl dd { margin: 0; text-align: right; font-weight: 500; font-variant-numeric: tabular-nums; }
.sr-callout { padding: var(--space-6); border-radius: var(--radius-lg); border: 1px solid var(--border); background: var(--bg-card); font-size: 20px; line-height: 30px; letter-spacing: -.01em; text-wrap: pretty; }
.sr-callout b { color: var(--up); font-weight: 600; }
.sr-callout small { display: block; margin-top: var(--space-3); font-size: 13px; line-height: 18px; color: var(--text-tertiary); letter-spacing: 0; }
.sr-bar2 { display: grid; gap: var(--space-2); margin-top: var(--space-4); }
.sr-bar2 div { display: grid; grid-template-columns: 120px minmax(0, 1fr) auto; align-items: center; gap: var(--space-3); font-size: 13px; color: var(--text-secondary); }

/* Injected runs */
.sr-inject { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 260px), 1fr)); gap: var(--space-5); }
.sr-inject .ac-card { display: grid; gap: var(--space-3); }

/* Toast */
.sr-toast { position: fixed; left: 50%; bottom: calc(24px + env(safe-area-inset-bottom, 0px)); transform: translate(-50%, 16px); padding: var(--space-2) var(--space-4); border-radius: var(--radius-md); background: var(--bg-button); color: var(--text-on-button); font-size: 14px; box-shadow: var(--shadow-menu); opacity: 0; pointer-events: none; transition: opacity .2s ease, transform .35s var(--ease-settle); z-index: 20; }
.sr-toast.is-on { opacity: 1; transform: translate(-50%, 0); }

.sr-more { margin-top: var(--space-4); }
.ac-table td.sr-wrap { white-space: normal; min-width: 260px; max-width: 520px; color: var(--text-secondary); }
.ac-table td.sr-check { white-space: normal; min-width: 220px; max-width: 360px; font-family: var(--font-mono); font-size: 12px; line-height: 17px; color: var(--text-tertiary); }
.ac-table a { text-decoration: none; }
@media (hover: hover) { .ac-table a:hover { text-decoration: underline; text-underline-offset: 3px; } }

@media (max-width: 560px) {
  .sr-section-title { margin-top: var(--space-8); }
  .sr-finding summary { grid-template-columns: minmax(0, 1fr); }
  .sr-finding-conf { justify-items: start; }
  .sr-bar2 div { grid-template-columns: 90px minmax(0, 1fr) auto; }
  .sr-callout { font-size: 17px; line-height: 26px; }
}

/* ── Motion. All of it is gone under reduced motion. ─────────────────────── */
@media (prefers-reduced-motion: no-preference) {
  /* Every screen enters in order: header, then each block, landing with weight */
  .sr-enter > * { animation: sr-rise var(--dur-enter) var(--ease-settle) both; animation-delay: calc(var(--i, 0) * var(--stagger)); }

  /* Headline words come up out of their line */
  .sr-play .ac-hero-xl .w > span { animation: sr-word .9s var(--ease-settle) both; animation-delay: calc(120ms + var(--w) * 38ms); }
  .sr-play .ac-hero-xl em { animation: sr-underline .8s var(--ease-settle) both; animation-delay: 1.9s; }
  .sr-play .ac-lede, .sr-play .ac-figures { animation: sr-rise .8s var(--ease-settle) both; animation-delay: .55s; }
  .sr-play .ac-figures { animation-delay: .7s; }

  /* Matrix: squares stamp in as a diagonal wave; each row's score turns green as its wave lands */
  .sr-play .ac-cells i { animation: sr-stamp .55s var(--ease-settle) both; animation-delay: calc(700ms + var(--r) * 85ms + var(--c) * 45ms); }
  .sr-play .ac-mscore.ac-up { animation: sr-score .5s ease both; animation-delay: calc(980ms + var(--r) * 85ms); }

  /* The loop: a single pulse runs the length of the line once, each step lights as it passes */
  .sr-play .sr-pulse { animation: sr-travel 2.4s var(--ease-press) .5s both; }
  .sr-play .sr-node-dot { animation: sr-node .5s ease both; animation-delay: calc(.55s + var(--n) * 330ms); }

  /* ProofChain plays left to right; the claimed number is struck through last */
  .sr-chain-play .ac-step { animation: sr-rise .7s var(--ease-settle) both; animation-delay: calc(var(--s) * 420ms); }
  .sr-chain-play .ac-step:not(:last-child)::after { animation: sr-draw .4s ease both; animation-delay: calc(var(--s) * 420ms + 300ms); transform-origin: left; }
  .sr-chain-play .ac-struck::after { animation: sr-draw .5s var(--ease-settle) both; animation-delay: 1.75s; }
  .sr-chain-play .sr-stamp { animation: sr-stamp .55s var(--ease-settle) both; animation-delay: 2.1s; }

  /* Chart columns rise in sequence */
  .ac-chart .bar-up, .ac-chart .bar-down, .ac-chart .bar-accent, .ac-chart .bar-neutral { transform-box: fill-box; transform-origin: bottom; animation: ac-rise .75s var(--ease-settle) both; animation-delay: calc(var(--i, 0) * 45ms); }
  .ac-chart rect:nth-of-type(4n) { animation-delay: calc(var(--i, 0) * 45ms); }

  /* Planted grid cells */
  .sr-play-cells .ac-cell { animation: sr-rise .6s var(--ease-settle) both; animation-delay: calc(var(--i) * 55ms); }
  .sr-play-cells .ac-cell-mark { animation: sr-stamp .5s var(--ease-settle) both; animation-delay: calc(150ms + var(--i) * 55ms); }

  /* Replay: rows wait dimmed, then light one by one */
  .sr-tl.is-replaying .sr-tl-row { opacity: .28; }
  .sr-tl.is-replaying .sr-tl-row.is-lit { opacity: 1; }
  .sr-tl-row.is-lit .sr-tl-dot { animation: sr-stamp .45s var(--ease-settle) both; }
  .sr-tl-row.is-lit .sr-decision { animation: sr-rise .5s var(--ease-settle) both; }

  ::view-transition-old(main) { animation: sr-out .22s ease both; }
  ::view-transition-new(main) { animation: sr-in .5s var(--ease-settle) both; }
}

@keyframes sr-rise { from { opacity: 0; transform: translateY(16px); } to { opacity: 1; transform: none; } }
@keyframes sr-word { from { transform: translateY(105%); } to { transform: none; } }
@keyframes sr-underline { from { background-size: 0% 3px; } to { background-size: 100% 3px; } }
@keyframes sr-stamp { 0% { opacity: 0; transform: scale(.25); } 60% { opacity: 1; transform: scale(1.14); } 100% { opacity: 1; transform: scale(1); } }
@keyframes sr-score { from { color: var(--text-tertiary); } to { color: var(--up); } }
@keyframes sr-travel { 0% { opacity: 0; left: 4%; } 6% { opacity: 1; } 94% { opacity: 1; } 100% { opacity: 0; left: 96%; } }
@keyframes sr-node { 0% { border-color: var(--border-control); } 40% { border-color: var(--up); color: var(--up); transform: scale(1.08); } 100% { transform: none; } }
@keyframes sr-draw { from { transform: scaleX(0); } to { transform: scaleX(1); } }
@keyframes sr-out { to { opacity: 0; transform: translateY(-6px); } }
@keyframes sr-in { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: none; } }

/* Spend Radar site. Reads window.SPEND_RADAR_DATA (written by `python -m spendradar export`) and renders it.
 * Rule from the design system: show, never compute. Values are printed as exported; the page only picks,
 * sorts and formats them. */
(function () {
  "use strict";

  var D = window.SPEND_RADAR_DATA;
  var REPO = "https://github.com/akarsh-dhingra/SpeedRadar-NeetHack";
  var BLOB = REPO + "/blob/main/";
  var REDUCED = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  var WORDS = ["zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten", "eleven", "twelve"];

  var VIEWS = [
    { id: "overview", label: "Overview", icon: "grid", group: "Evidence" },
    { id: "run", label: "Run detail", icon: "file", group: "Evidence" },
