  var FONT = "'Fredoka', 'Baloo 2', system-ui, sans-serif", COMIC = "'Bangers', 'Fredoka', sans-serif", MONO = "'Geist Mono', ui-monospace, monospace";
  function txt(g, s, x, y, size, opts) {
