        if (lk > .9) { inkRR(g, b[1] - 20, b[2] - 50, measure(b[0], 46) + 50, 84, 40, C.white, 5); txt(g, b[0], b[1] + 5, b[2] + 8, 46, { fill: C.ink }); }
